         WHEN daily.model_roll < 0.93 THEN 'gemini-2.5-pro'
         ELSE 'gemini-2.5-flash'
       END,
       daily.usage_date
FROM employee_days daily
CROSS JOIN LATERAL generate_series(1, daily.request_count) AS requests(request_no)
